public:
    int maxScore(vector<vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        vector<vector<int>> dp(R, vector<int>(C, 1e9));
        int ans = -1e9;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                int prev_min = 1e9;
                if (r > 0) prev_min = min({prev_min, dp[r - 1][c], grid[r - 1][c]});
                if (c > 0) prev_min = min({prev_min, dp[r][c - 1], grid[r][c - 1]});
