class Solution {
    public int maxScore(List<List<Integer>> grid) {
        int R = grid.size(), C = grid.get(0).size();
        int[][] dp = new int[R][C];
        int ans = (int) -1e9;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int val = grid.get(r).get(c);
                int prevMin = (int) 1e9;
                if (r > 0) prevMin = Math.min(prevMin, Math.min(dp[r - 1][c], grid.get(r - 1).get(c)));
                if (c > 0) prevMin = Math.min(prevMin, Math.min(dp[r][c - 1], grid.get(r).get(c - 1)));
                if (prevMin != (int) 1e9) {
                    ans = Math.max(ans, val - prevMin);
                }
                dp[r][c] = Math.min(val, prevMin);
            }
        }
        return ans;
    }
}

var maxScore = function(grid) {
    const R = grid.length, C = grid[0].length;
    const dp = Array.from({length: R}, () => new Array(C).fill(Infinity));
    let ans = -Infinity;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            let prevMin = Infinity;
            if (r > 0) prevMin = Math.min(prevMin, dp[r - 1][c], grid[r - 1][c]);
            if (c > 0) prevMin = Math.min(prevMin, dp[r][c - 1], grid[r][c - 1]);
            if (prevMin !== Infinity) {
                ans = Math.max(ans, grid[r][c] - prevMin);
            }
            dp[r][c] = Math.min(grid[r][c], prevMin);
        }
    }
    return ans;
};
